CREATE TABLE tenants (id VARCHAR(64) PRIMARY KEY, name VARCHAR(160) NOT NULL);
CREATE TABLE fleets (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id), name VARCHAR(160) NOT NULL, region VARCHAR(80) NOT NULL);
CREATE TABLE oems (id VARCHAR(32) PRIMARY KEY, name VARCHAR(100) NOT NULL, color VARCHAR(20) NOT NULL);
CREATE TABLE vehicles (vin VARCHAR(17) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id), fleet_id VARCHAR(64) NOT NULL REFERENCES fleets(id), oem_id VARCHAR(32) NOT NULL REFERENCES oems(id), registration VARCHAR(30) NOT NULL, model VARCHAR(80) NOT NULL, driver_name VARCHAR(80) NOT NULL, powertrain VARCHAR(16) NOT NULL);
CREATE INDEX ix_vehicle_tenant ON vehicles(tenant_id, vin);
CREATE INDEX ix_vehicle_fleet ON vehicles(tenant_id, fleet_id, vin);
CREATE TABLE mappings (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL REFERENCES tenants(id), oem_id VARCHAR(32) NOT NULL REFERENCES oems(id), schema_version VARCHAR(24) NOT NULL, version INTEGER NOT NULL, status VARCHAR(20) NOT NULL, rules TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, approved_by VARCHAR(160), approved_at TIMESTAMP WITH TIME ZONE, UNIQUE(tenant_id, oem_id, schema_version, version));
CREATE TABLE raw_events (id VARCHAR(100) NOT NULL, tenant_id VARCHAR(64) NOT NULL, vin VARCHAR(17) NOT NULL, oem_id VARCHAR(32) NOT NULL, schema_version VARCHAR(24) NOT NULL, event_time TIMESTAMP WITH TIME ZONE NOT NULL, received_at TIMESTAMP WITH TIME ZONE NOT NULL, sequence_no BIGINT NOT NULL, payload TEXT NOT NULL, status VARCHAR(24) NOT NULL, reason VARCHAR(500), mapping_id VARCHAR(64), normalized TEXT, processed_at TIMESTAMP WITH TIME ZONE, PRIMARY KEY(tenant_id,id));
CREATE INDEX ix_event_recent ON raw_events(tenant_id, received_at DESC, id);
CREATE INDEX ix_event_quarantine ON raw_events(tenant_id, oem_id, status, received_at);
CREATE INDEX ix_event_vehicle ON raw_events(tenant_id, vin, event_time DESC);
CREATE TABLE vehicle_state (vin VARCHAR(17) PRIMARY KEY REFERENCES vehicles(vin), tenant_id VARCHAR(64) NOT NULL, event_time TIMESTAMP WITH TIME ZONE NOT NULL, event_id VARCHAR(100) NOT NULL, speed_kmh DOUBLE PRECISION, soc_pct DOUBLE PRECISION, odometer_km DOUBLE PRECISION, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, dtc TEXT NOT NULL, quality VARCHAR(24) NOT NULL);
CREATE INDEX ix_state_tenant ON vehicle_state(tenant_id, event_time DESC);
CREATE TABLE alerts (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, vin VARCHAR(17) NOT NULL, event_id VARCHAR(100) NOT NULL, oem_id VARCHAR(32) NOT NULL, kind VARCHAR(32) NOT NULL, severity VARCHAR(16) NOT NULL, title VARCHAR(200) NOT NULL, description VARCHAR(1000) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, assigned_to VARCHAR(160), UNIQUE(tenant_id,event_id,kind));
CREATE INDEX ix_alert_tenant ON alerts(tenant_id,status,created_at DESC,id);
CREATE TABLE incidents (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, oem_id VARCHAR(32) NOT NULL, schema_version VARCHAR(24) NOT NULL, title VARCHAR(200) NOT NULL, description VARCHAR(1000) NOT NULL, status VARCHAR(24) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, resolved_at TIMESTAMP WITH TIME ZONE, UNIQUE(tenant_id,oem_id,schema_version));
CREATE TABLE replay_jobs (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, oem_id VARCHAR(32) NOT NULL, status VARCHAR(24) NOT NULL, total INTEGER NOT NULL, recovered INTEGER NOT NULL, failed INTEGER NOT NULL, requested_by VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, completed_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE audit_log (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, actor VARCHAR(160) NOT NULL, action VARCHAR(64) NOT NULL, resource VARCHAR(200) NOT NULL, detail TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_audit_tenant ON audit_log(tenant_id,created_at DESC,id);
CREATE TABLE telemetry_revisions (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, event_id VARCHAR(100) NOT NULL, mapping_id VARCHAR(64) NOT NULL, normalized TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(tenant_id,event_id,mapping_id));
CREATE TABLE erasures (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, subject_hash VARCHAR(80) NOT NULL, requested_by VARCHAR(160) NOT NULL, status VARCHAR(24) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
